-- ============================================================================
-- 0004 · Carry the engine's own generation id
--
-- WHY THIS IS NEEDED
-- ------------------
-- `creative_runs.id` is `uuid`, and 0001 assumed the engine's generation id
-- could fill it. It cannot: the engine mints ids like
-- `gen_1790178671861_gh540`, which is not a UUID and is rejected by the type.
--
-- The first real render after 0003 proved it. The request row landed (its id
-- is generated by the database) and the run did not, because the insert failed
-- on the primary key -- silently, since `recordSafely` swallows errors so that
-- a persistence problem can never fail a render. The safety rule worked
-- exactly as designed and hid the defect, which is the trade that rule makes.
--
-- THE FIX, AND WHY NOT THE OTHER ONE
-- -----------------------------------
-- The alternative was changing `id` to `text`. That was rejected: the column
-- is referenced by five foreign keys, a UUID primary key is right for a
-- database, and the engine's id format is the engine's business and has
-- changed before.
--
-- So the run keeps a real UUID, derived deterministically from the engine id
-- (UUIDv5 over a fixed namespace) so that persisting the same render twice is
-- idempotent rather than duplicating it. The engine's own id is stored
-- alongside, because the render logs, the delivery folders on disk and the API
-- response all speak in `gen_...` and a row nobody can correlate to those is
-- a row nobody will use.
-- ============================================================================

alter table public.creative_runs
  add column if not exists engine_generation_id text;

-- Unique rather than a plain index: two rows claiming the same engine render
-- would make "which row is this render" unanswerable, and the deterministic
-- UUID above already guarantees one row per engine id. This enforces it at the
-- level that cannot be bypassed by a bug in the mapping.
create unique index if not exists creative_runs_engine_generation_id_key
  on public.creative_runs (engine_generation_id)
  where engine_generation_id is not null;

comment on column public.creative_runs.engine_generation_id is
  'The image engine''s own id (gen_...). The primary key is a UUIDv5 derived from it.';
